"""Shared, scoped styling for scientific plots generated by the project.

The palette is built on five colours chosen by the user (ink black, wine black, burgundy, dusty
rose and cream), extended with validated companion hues only where a job needs more than they
give. Its roles, rules and validator live in the `color-palette` skill. Change a value here only
after re-running `.agents/skills/color-palette/scripts/validate_palette.py`.
"""

from __future__ import annotations

from functools import wraps

import matplotlib
from cycler import cycler

# ---- the five base colours (priority: use these before anything derived) -----------------------
INK_BLACK = "#0A0B0F"
WINE_BLACK = "#1E1216"
BURGUNDY = "#7B2032"
ROSE = "#C2A19A"
CREAM = "#FFF7F1"
BASE_COLORS = (INK_BLACK, WINE_BLACK, BURGUNDY, ROSE, CREAM)

# Base colours kept on purpose even where a generic check would move them (validator reports
# them as WARN, not FAIL): burgundy sits just below the light-mode lightness band.
ANCHORS = frozenset({BURGUNDY})

# ---- surfaces and text, per mode --------------------------------------------------------------
SURFACE = {"light": CREAM, "dark": WINE_BLACK}
PAGE = {"light": CREAM, "dark": INK_BLACK}
TEXT = {"light": WINE_BLACK, "dark": CREAM}
MUTED = {"light": "#6B5559", "dark": ROSE}
BORDER = {"light": "#E6D6D1", "dark": "#3A2A2E"}
REFERENCE = {"light": "#9B8385", "dark": "#8C7A7C"}  # context/reference lines, >= 3:1 on surface

INK = TEXT["light"]
MUTED_INK = MUTED["light"]
GRID = BORDER["light"]
REFERENCE_LINE = REFERENCE["light"]
TINT = "#F3E6E1"   # table headers, callouts, secondary panels (between cream and rose)
LINK = BURGUNDY

# ---- categorical: fixed order, never cycled past eight ---------------------------------------
# Slot 1 is the user's burgundy; the rest are companion hues ordered for CVD separation:
# burgundy, blue, ochre, violet, terracotta, cyan, olive, teal. The first three also separate
# all-pairs (scatter, small multiples), so no red-green pair sits among them.
CATEGORICAL = {
    "light": ("#7B2032", "#2B7EC9", "#A46E01", "#8864C0",
              "#BC5A29", "#089AC3", "#7F8002", "#09A0A0"),
    "dark": ("#B83D54", "#398AD6", "#B37903", "#9470CD",
             "#C96736", "#0994BA", "#8C8C06", "#05A7A7"),
}
CATEGORICAL_8 = CATEGORICAL["light"]
PRIMARY = CATEGORICAL_8[0]  # burgundy: the proposed method / the one series that matters
ACCENT = CATEGORICAL_8[1]   # blue: the contrasting series (loss, centralized, focal comparison)

# ---- sequential, diverging, status -----------------------------------------------------------
# Built from the base colours: cream -> rose -> burgundy -> wine black (OKLab midpoints between).
SEQUENTIAL = ("#FFF7F1", "#E0CBC5", "#C2A19A", "#A16264", "#7B2032", "#4B1B24", "#1E1216")
# Negative (blue) -> cream midpoint -> positive (rose, burgundy). `_r` puts burgundy on the low end.
DIVERGING = ("#1D4587", "#7E93B9", "#FFF7F1", "#C2A19A", "#7B2032")
STATUS = {
    "light": {"ok": "#23690D", "warning": "#8D5E05", "critical": "#B3261E", "info": "#005A9D"},
    "dark": {"ok": "#60A750", "warning": "#C38406", "critical": "#E26275", "info": "#4697E4"},
}

FOLD_COLORS = CATEGORICAL_8[:6]
LINE_STYLES = ("-", "--", ":", "-.")
MARKERS = ("o", "s", "^", "D", "P", "X")

EXPORT_DPI = 300
EMBED_DPI = 160

PLOT_RC = {
    "axes.axisbelow": True,
    "axes.edgecolor": GRID,
    "axes.facecolor": CREAM,
    "axes.grid": False,
    "axes.labelcolor": INK,
    "axes.prop_cycle": cycler(color=CATEGORICAL_8),
    "axes.spines.right": False,
    "axes.spines.top": False,
    "axes.titlecolor": INK,
    "axes.titleweight": "semibold",
    "figure.facecolor": CREAM,
    "font.family": "sans-serif",
    "grid.alpha": 0.8,
    "grid.color": GRID,
    "grid.linewidth": 0.7,
    "image.cmap": "palette_sequential",
    "legend.frameon": False,
    "savefig.facecolor": CREAM,
    "text.color": INK,
    "xtick.color": MUTED_INK,
    "ytick.color": MUTED_INK,
}

METRIC_COLORS = {
    "loss": ACCENT,
    "dice": PRIMARY,
    "iou": CATEGORICAL_8[4],
    "balanced_accuracy": PRIMARY,
    "macro_f1": CATEGORICAL_8[4],
    "accuracy": MUTED_INK,
    "auc": PRIMARY,
    "auc_ovr_macro": PRIMARY,
}


def _register_colormaps():
    from matplotlib.colors import LinearSegmentedColormap

    for name, colors in (("palette_sequential", SEQUENTIAL), ("palette_diverging", DIVERGING)):
        for suffix, ordered in (("", colors), ("_r", colors[::-1])):
            if name + suffix not in matplotlib.colormaps:
                matplotlib.colormaps.register(
                    LinearSegmentedColormap.from_list(name + suffix, list(ordered)))


_register_colormaps()


def colormap(name="sequential"):
    """Return the registered `palette_<name>` colormap (sequential, diverging; `_r` reverses)."""
    return matplotlib.colormaps[f"palette_{name}"]


def with_plot_style(function):
    """Run one plot builder in an rc context without mutating global Matplotlib state."""
    @wraps(function)
    def wrapped(*args, **kwargs):
        with matplotlib.rc_context(PLOT_RC):
            return function(*args, **kwargs)
    return wrapped


def categorical_color(index):
    return CATEGORICAL_8[int(index) % len(CATEGORICAL_8)]


def fold_style(index):
    index = int(index)
    return {
        "color": FOLD_COLORS[index % len(FOLD_COLORS)],
        "linestyle": LINE_STYLES[index % len(LINE_STYLES)],
        "marker": MARKERS[index % len(MARKERS)],
    }


def metric_color(metric_name, fallback_index=0):
    name = str(metric_name).lower()
    if name in METRIC_COLORS:
        return METRIC_COLORS[name]
    if "loss" in name:
        return ACCENT
    if "auc" in name:
        return METRIC_COLORS["auc"]
    return categorical_color(fallback_index)


def setup_color(label, fallback_index=0):
    """Keep experimental setup colors stable across reports and plot orderings."""
    name = str(label).lower().replace("_", "-")
    if "local" in name or "standalone" in name:
        return MUTED_INK
    if "central" in name:
        return ACCENT
    if "federat" in name or "fedper" in name:
        return PRIMARY
    return categorical_color(fallback_index)


def split_style(split, phase="", fallback_index=0):
    """Differentiate training/evaluation traces without relying on color alone."""
    split = str(split).lower()
    phase = str(phase).lower()
    if split in {"val", "validation"}:
        return {"linestyle": "-", "marker": "o"}
    if split == "test":
        return {"linestyle": ":", "marker": "^"}
    if "step" in phase:
        return {"linestyle": "--", "marker": None}
    if split == "train":
        return {"linestyle": "--", "marker": "s"}
    return {
        "linestyle": LINE_STYLES[int(fallback_index) % len(LINE_STYLES)],
        "marker": MARKERS[int(fallback_index) % len(MARKERS)],
    }


def style_axis(axis, *, grid_axis="y"):
    axis.set_axisbelow(True)
    axis.grid(True, axis=grid_axis, color=GRID, alpha=0.8, linewidth=0.7)
    axis.spines["top"].set_visible(False)
    axis.spines["right"].set_visible(False)
    axis.spines["left"].set_color(GRID)
    axis.spines["bottom"].set_color(GRID)
